/* LeaveGrantEngineMapper.selectLatestUnappliedHandling */
SELECT
      H.HIST_ID       AS HIST_ID
    , H.HANDLING_TYPE AS HANDLING_TYPE
  FROM TB_USER_HIRE_DATE_HISTORY H
 WHERE H.CMPNY_CD   = #{cmpnyCd}
   AND H.USER_CD    = #{userCd}
   AND H.APPLIED_YN = 'N'
 ORDER BY H.INSERT_DATE DESC, H.HIST_ID DESC
 LIMIT 1

/* LeaveGrantEngineMapper.selectActiveStatutoryGrantIds */
SELECT
      G.GRANT_ID
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.DEL_YN   = 'N'
   AND G.GRANT_TYPE LIKE 'STATUTORY\_%'
   AND G.STATUS IN ('ACTIVE', 'EXHAUSTED')
 ORDER BY G.GRANT_ID ASC

mapper.update:
/* LeaveGrantEngineMapper.markHireDateHistoryApplied */
UPDATE TB_USER_HIRE_DATE_HISTORY
   SET APPLIED_YN   = 'Y'
     , APPLIED_DATE = NOW()
     , APPLIED_BY   = #{appliedBy}
 WHERE CMPNY_CD   = #{cmpnyCd}
   AND USER_CD    = #{userCd}
   AND APPLIED_YN = 'N'

mapper.select:
/* LeaveGrantEngineMapper.selectRecallableStatutoryTotal */
SELECT COALESCE(SUM(G.GRANT_DAYS - G.USED_DAYS), 0)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.GRANT_TYPE LIKE 'STATUTORY\_%'

/* LeaveGrantEngineMapper.selectActiveStatutoryGrantedTotal */
SELECT COALESCE(SUM(G.GRANT_DAYS), 0)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.GRANT_TYPE LIKE 'STATUTORY\_%'

mapper.update:
/* LeaveGrantEngineMapper.cancelStatutoryGrantForHireChange */
UPDATE TB_USER_LEAVE_GRANT
   SET STATUS        = 'CANCELED'
     , CANCEL_REASON = #{reason}
     , CANCEL_DATE   = NOW()
     , CANCEL_BY     = #{operatorUserCd}
     , GRANT_REASON  = #{grantReason}
     , UPDATE_NO     = #{operatorUserCd}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND GRANT_ID = #{grantId}
   AND STATUS   = 'ACTIVE'
   AND DEL_YN   = 'N'

/* LeaveGrantEngineMapper.reduceStatutoryGrantDaysForHireChange */
UPDATE TB_USER_LEAVE_GRANT
   SET GRANT_DAYS   = GRANT_DAYS - #{reduceDays}
     , GRANT_REASON = #{grantReason}
     , UPDATE_NO    = #{operatorUserCd}
     , UPDATE_DATE  = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND GRANT_ID = #{grantId}
   AND STATUS   = 'ACTIVE'
   AND DEL_YN   = 'N'
   AND (GRANT_DAYS - USED_DAYS) >= #{reduceDays}
